css:
.print-format {
	font-family: "IBM Plex Sans", "Helvetica Neue", "Segoe UI", Arial, sans-serif;
	font-size: 9pt;
	color: #161616;
}

.print-heading {
	border-bottom: 1px solid #c6c6c6;
	padding-bottom: 8px;
	margin-bottom: 16px;
	color: #161616;
}

.print-heading h2 {
	font-size: 20pt;
	font-weight: 400;
	letter-spacing: 0;
}

.print-heading small {
	color: #525252;
	font-size: 9pt;
}

.print-format table.table {
	border-collapse: collapse;
}

.print-format table.table thead th {
	background-color: #e0e0e0;
	color: #161616;
	font-weight: 600;
	border: none;
	border-bottom: 1px solid #c6c6c6;
	text-transform: none;
	font-size: 9pt;
	padding: 8px;
}

.print-format table.table td {
	border: none;
	border-bottom: 1px solid #e0e0e0;
	padding: 8px;
	vertical-align: top;
}

.print-format .letter-head {
	margin-bottom: 24px;
}

.print-format .important .value {
	font-size: 11pt;
	font-weight: 600;
}

.print-format label {
	color: #525252;
	font-size: 8pt;
	font-weight: 400;
	letter-spacing: 0.32px;
	margin-bottom: 2px;
}

.print-format .section-break {
	border-bottom: 1px solid #e0e0e0;
	padding-bottom: 12px;
	margin-bottom: 12px;
}

.print-format .comment-block,
.print-format blockquote {
	border-left: 3px solid #8d8d8d;
	padding-left: 12px;
	color: #525252;
}
